1085  static parse_buffer *buffer_skip_whitespace(parse_buffer * const buffer)
1086  {
1087      if ((buffer == NULL) || (buffer->content == NULL))
1088      {
1089          return NULL;
1090      }
1091  
1092      if (cannot_access_at_index(buffer, 0))
1093      {
1094          return buffer;
1095      }
1096  
1097      while (can_access_at_index(buffer, 0) && (buffer_at_offset(buffer)[0] <= 32))
1098      {
1099         buffer->offset++;
1100      }
1101  
1102      if (buffer->offset == buffer->length)
1103      {
1104          buffer->offset--;
1105      }
1106  
1107      return buffer;
1108  }

1111  static parse_buffer *skip_utf8_bom(parse_buffer * const buffer)
1112  {
1113      if ((buffer == NULL) || (buffer->content == NULL) || (buffer->offset != 0))
1114      {
1115          return NULL;
1116      }
1117  
1118      if (can_access_at_index(buffer, 4) && (strncmp((const char*)buffer_at_offset(buffer), "\xEF\xBB\xBF", 3) == 0))
1119      {
1120          buffer->offset += 3;
1121      }
1122  
1123      return buffer;
1124  }

1126  CJSON_PUBLIC(cJSON *) cJSON_ParseWithOpts(const char *value, const char **return_parse_end, cJSON_bool require_null_terminated)
1127  {
1128      size_t buffer_length;
1129  
1130      if (NULL == value)
1131      {
1132          return NULL;
1133      }
1134  
1135      /* Adding null character size due to require_null_terminated. */
1136      buffer_length = strlen(value) + sizeof("");
1137  
1138      return cJSON_ParseWithLengthOpts(value, buffer_length, return_parse_end, require_null_terminated);
