1363  static cJSON_bool parse_value(cJSON * const item, parse_buffer * const input_buffer)
1364  {
1365      if ((input_buffer == NULL) || (input_buffer->content == NULL))
1366      {
1367          return false; /* no input */
1368      }
1369  
1370      /* parse the different types of values */
1371      /* null */
1372      if (can_read(input_buffer, 4) && (strncmp((const char*)buffer_at_offset(input_buffer), "null", 4) == 0))
1373      {
1374          item->type = cJSON_NULL;
1375          input_buffer->offset += 4;
1376          return true;
1377      }
1378      /* false */
1379      if (can_read(input_buffer, 5) && (strncmp((const char*)buffer_at_offset(input_buffer), "false", 5) == 0))
1380      {
1381          item->type = cJSON_False;
1382          input_buffer->offset += 5;
1383          return true;
1384      }
1385      /* true */
1386      if (can_read(input_buffer, 4) && (strncmp((const char*)buffer_at_offset(input_buffer), "true", 4) == 0))
1387      {
1388          item->type = cJSON_True;
1389          item->valueint = 1;
1390          input_buffer->offset += 4;
1391          return true;
1392      }
1393      /* string */
1394      if (can_access_at_index(input_buffer, 0) && (buffer_at_offset(input_buffer)[0] == '\"'))
1395      {
1396          return parse_string(item, input_buffer);
1397      }
1398      /* number */
1399      if (can_access_at_index(input_buffer, 0) && ((buffer_at_offset(input_buffer)[0] == '-') || ((buffer_at_offset(input_buffer)[0] >= '0') && (buffer_at_offset(input_buffer)[0] <= '9'))))
1400      {
1401          return parse_number(item, input_buffer);
1402      }
1403      /* array */
1404      if (can_access_at_index(input_buffer, 0) && (buffer_at_offset(input_buffer)[0] == '['))
1405      {
1406          return parse_array(item, input_buffer);
1407      }
1408      /* object */
1409      if (can_access_at_index(input_buffer, 0) && (buffer_at_offset(input_buffer)[0] == '{'))
1410      {
1411          return parse_object(item, input_buffer);
1412      }
1413  
1414      return false;
1415  }

1418  static cJSON_bool print_value(const cJSON * const item, printbuffer * const output_buffer)
1419  {
1420      unsigned char *output = NULL;
1421  
1422      if ((item == NULL) || (output_buffer == NULL))
1423      {
1424          return false;
1425      }
1426  
1427      switch ((item->type) & 0xFF)
1428      {
1429          case cJSON_NULL:
1430              output = ensure(output_buffer, 5);
1431              if (output == NULL)
1432              {
1433                  return false;
1434              }
1435              strcpy((char*)output, "null");
1436              return true;
1437  
1438          case cJSON_False:
1439              output = ensure(output_buffer, 6);
1440              if (output == NULL)
1441              {
1442                  return false;
1443              }
1444              strcpy((char*)output, "false");
1445              return true;
1446  
1447          case cJSON_True:
1448              output = ensure(output_buffer, 5);
1449              if (output == NULL)
1450              {
1451                  return false;
1452              }
1453              strcpy((char*)output, "true");
1454              return true;
1455  
1456          case cJSON_Number:
1457              return print_number(item, output_buffer);
1458  
1459          case cJSON_Raw:
1460          {
1461              size_t raw_length = 0;
1462              if (item->valuestring == NULL)
1463              {
1464                  return false;
1465              }
1466  
1467              raw_length = strlen(item->valuestring) + sizeof("");
1468              output = ensure(output_buffer, raw_length);
1469              if (output == NULL)
1470              {
1471                  return false;
1472              }
1473              memcpy(output, item->valuestring, raw_length);
1474              return true;
1475          }
1476  
1477          case cJSON_String:
1478              return print_string(item, output_buffer);
1479  
1480          case cJSON_Array:
1481              return print_array(item, output_buffer);
1482  
1483          case cJSON_Object:
1484              return print_object(item, output_buffer);
1485  
1486          default:
1487              return false;
1488      }
1489  }

1492  static cJSON_bool parse_array(cJSON * const item, parse_buffer * const input_buffer)
1493  {
1494      cJSON *head = NULL; /* head of the linked list */
1495      cJSON *current_item = NULL;
1496  
1497      if (input_buffer->depth >= CJSON_NESTING_LIMIT)
1498      {
1499          return false; /* to deeply nested */
1500      }
1501      input_buffer->depth++;
1502  
1503      if (buffer_at_offset(input_buffer)[0] != '[')
1504      {
1505          /* not an array */
1506          goto fail;
1507      }
1508  
1509      input_buffer->offset++;
1510      buffer_skip_whitespace(input_buffer);
1511      if (can_access_at_index(input_buffer, 0) && (buffer_at_offset(input_buffer)[0] == ']'))
1512      {
1513          /* empty array */
1514          goto success;
1515      }
1516  
1517      /* check if we skipped to the end of the buffer */
1518      if (cannot_access_at_index(input_buffer, 0))
1519      {
1520          input_buffer->offset--;
1521          goto fail;
1522      }
1523  
1524      /* step back to character in front of the first element */
1525      input_buffer->offset--;
1526      /* loop through the comma separated array elements */
1527      do
1528      {
1529          /* allocate next item */
1530          cJSON *new_item = cJSON_New_Item(&(input_buffer->hooks));
1531          if (new_item == NULL)
1532          {
1533              goto fail; /* allocation failure */
1534          }
1535  
1536          /* attach next item to list */
1537          if (head == NULL)
1538          {
1539              /* start the linked list */
1540              current_item = head = new_item;
1541          }
1542          else
1543          {
1544              /* add to the end and advance */
1545              current_item->next = new_item;
1546              new_item->prev = current_item;
1547              current_item = new_item;
1548          }
1549  
1550          /* parse next value */
1551          input_buffer->offset++;
1552          buffer_skip_whitespace(input_buffer);
1553          if (!parse_value(current_item, input_buffer))
1554          {
1555              goto fail; /* failed to parse value */
1556          }
1557          buffer_skip_whitespace(input_buffer);
1558      }
1559      while (can_access_at_index(input_buffer, 0) && (buffer_at_offset(input_buffer)[0] == ','));
1560  
1561      if (cannot_access_at_index(input_buffer, 0) || buffer_at_offset(input_buffer)[0] != ']')
1562      {
1563          goto fail; /* expected end of array */
1564      }
1565  
1566  success:
1567      input_buffer->depth--;
1568  
1569      if (head != NULL) {
1570          head->prev = current_item;
1571      }
1572  
1573      item->type = cJSON_Array;
1574      item->child = head;
1575  
1576      input_buffer->offset++;
1577  
1578      return true;
1579  
1580  fail:
1581      if (head != NULL)
1582      {
1583          cJSON_Delete(head);
1584      }
1585  
1586      return false;
1587  }

1590  static cJSON_bool print_array(const cJSON * const item, printbuffer * const output_buffer)
1591  {
1592      unsigned char *output_pointer = NULL;
1593      size_t length = 0;
1594      cJSON *current_element = item->child;
1595  
1596      if (output_buffer == NULL)
1597      {
1598          return false;
1599      }
1600  
1601      /* Compose the output array. */
1602      /* opening square bracket */
1603      output_pointer = ensure(output_buffer, 1);
1604      if (output_pointer == NULL)
1605      {
1606          return false;
1607      }
1608  
1609      *output_pointer = '[';
1610      output_buffer->offset++;
1611      output_buffer->depth++;
1612  
1613      while (current_element != NULL)
1614      {
1615          if (!print_value(current_element, output_buffer))
1616          {
1617              return false;
1618          }
1619          update_offset(output_buffer);
1620          if (current_element->next)
1621          {
1622              length = (size_t) (output_buffer->format ? 2 : 1);
1623              output_pointer = ensure(output_buffer, length + 1);
1624              if (output_pointer == NULL)
1625              {
1626                  return false;
1627              }
1628              *output_pointer++ = ',';
1629              if(output_buffer->format)
1630              {
1631                  *output_pointer++ = ' ';
1632              }
1633              *output_pointer = '\0';
1634              output_buffer->offset += length;
1635          }
1636          current_element = current_element->next;
1637      }
1638  
1639      output_pointer = ensure(output_buffer, 2);
1640      if (output_pointer == NULL)
1641      {
1642          return false;
1643      }
1644      *output_pointer++ = ']';
1645      *output_pointer = '\0';
1646      output_buffer->depth--;
1647  
1648      return true;
1649  }

1652  static cJSON_bool parse_object(cJSON * const item, parse_buffer * const input_buffer)
1653  {
1654      cJSON *head = NULL; /* linked list head */
1655      cJSON *current_item = NULL;
1656  
1657      if (input_buffer->depth >= CJSON_NESTING_LIMIT)
1658      {
1659          return false; /* to deeply nested */
1660      }
1661      input_buffer->depth++;
1662  
1663      if (cannot_access_at_index(input_buffer, 0) || (buffer_at_offset(input_buffer)[0] != '{'))
1664      {
1665          goto fail; /* not an object */
1666      }
1667  
1668      input_buffer->offset++;
1669      buffer_skip_whitespace(input_buffer);
1670      if (can_access_at_index(input_buffer, 0) && (buffer_at_offset(input_buffer)[0] == '}'))
1671      {
1672          goto success; /* empty object */
1673      }
1674  
1675      /* check if we skipped to the end of the buffer */
1676      if (cannot_access_at_index(input_buffer, 0))
1677      {
1678          input_buffer->offset--;
1679          goto fail;
1680      }
1681  
1682      /* step back to character in front of the first element */
1683      input_buffer->offset--;
1684      /* loop through the comma separated array elements */
1685      do
1686      {
1687          /* allocate next item */
1688          cJSON *new_item = cJSON_New_Item(&(input_buffer->hooks));
1689          if (new_item == NULL)
1690          {
1691              goto fail; /* allocation failure */
1692          }
1693  
1694          /* attach next item to list */
1695          if (head == NULL)
1696          {
1697              /* start the linked list */
1698              current_item = head = new_item;
1699          }
1700          else
1701          {
1702              /* add to the end and advance */
1703              current_item->next = new_item;
1704              new_item->prev = current_item;
1705              current_item = new_item;
1706          }
1707  
1708          if (cannot_access_at_index(input_buffer, 1))
1709          {
1710              goto fail; /* nothing comes after the comma */
1711          }
1712  
1713          /* parse the name of the child */
1714          input_buffer->offset++;
1715          buffer_skip_whitespace(input_buffer);
1716          if (!parse_string(current_item, input_buffer))
1717          {
1718              goto fail; /* failed to parse name */
1719          }
1720          buffer_skip_whitespace(input_buffer);
1721  
1722          /* swap valuestring and string, because we parsed the name */
1723          current_item->string = current_item->valuestring;
1724          current_item->valuestring = NULL;
1725  
1726          if (cannot_access_at_index(input_buffer, 0) || (buffer_at_offset(input_buffer)[0] != ':'))
1727          {
1728              goto fail; /* invalid object */
1729          }
1730  
1731          /* parse the value */
1732          input_buffer->offset++;
1733          buffer_skip_whitespace(input_buffer);
1734          if (!parse_value(current_item, input_buffer))
1735          {
1736              goto fail; /* failed to parse value */
1737          }
1738          buffer_skip_whitespace(input_buffer);
1739      }
1740      while (can_access_at_index(input_buffer, 0) && (buffer_at_offset(input_buffer)[0] == ','));
1741  
1742      if (cannot_access_at_index(input_buffer, 0) || (buffer_at_offset(input_buffer)[0] != '}'))
1743      {
1744          goto fail; /* expected end of object */
1745      }
1746  
1747  success:
1748      input_buffer->depth--;
1749  
1750      if (head != NULL) {
1751          head->prev = current_item;
1752      }
1753  
1754      item->type = cJSON_Object;
1755      item->child = head;
1756  
1757      input_buffer->offset++;
1758      return true;
1759  
1760  fail:
1761      if (head != NULL)
1762      {
1763          cJSON_Delete(head);
1764      }
1765  
1766      return false;
1767  }

1770  static cJSON_bool print_object(const cJSON * const item, printbuffer * const output_buffer)
1771  {
1772      unsigned char *output_pointer = NULL;
1773      size_t length = 0;
1774      cJSON *current_item = item->child;
1775  
1776      if (output_buffer == NULL)
1777      {
1778          return false;
1779      }
1780  
1781      /* Compose the output: */
1782      length = (size_t) (output_buffer->format ? 2 : 1); /* fmt: {\n */
1783      output_pointer = ensure(output_buffer, length + 1);
1784      if (output_pointer == NULL)
1785      {
1786          return false;
1787      }
1788  
1789      *output_pointer++ = '{';
1790      output_buffer->depth++;
1791      if (output_buffer->format)
1792      {
1793          *output_pointer++ = '\n';
1794      }
1795      output_buffer->offset += length;
1796  
1797      while (current_item)
1798      {
1799          if (output_buffer->format)
1800          {
1801              size_t i;
1802              output_pointer = ensure(output_buffer, output_buffer->depth);
1803              if (output_pointer == NULL)
1804              {
1805                  return false;
1806              }
1807              for (i = 0; i < output_buffer->depth; i++)
1808              {
1809                  *output_pointer++ = '\t';
1810              }
1811              output_buffer->offset += output_buffer->depth;
1812          }
1813  
1814          /* print key */
1815          if (!print_string_ptr((unsigned char*)current_item->string, output_buffer))
1816          {
1817              return false;
1818          }
1819          update_offset(output_buffer);
1820  
1821          length = (size_t) (output_buffer->format ? 2 : 1);
1822          output_pointer = ensure(output_buffer, length);
1823          if (output_pointer == NULL)
1824          {
1825              return false;
1826          }
1827          *output_pointer++ = ':';
1828          if (output_buffer->format)
1829          {
1830              *output_pointer++ = '\t';
1831          }
1832          output_buffer->offset += length;
1833  
1834          /* print value */
1835          if (!print_value(current_item, output_buffer))
1836          {
1837              return false;
1838          }
1839          update_offset(output_buffer);
1840  
1841          /* print comma if not last */
1842          length = ((size_t)(output_buffer->format ? 1 : 0) + (size_t)(current_item->next ? 1 : 0));
1843          output_pointer = ensure(output_buffer, length + 1);
1844          if (output_pointer == NULL)
1845          {
1846              return false;
1847          }
1848          if (current_item->next)
1849          {
1850              *output_pointer++ = ',';
1851          }
1852  
1853          if (output_buffer->format)
1854          {
1855              *output_pointer++ = '\n';
1856          }
1857          *output_pointer = '\0';
1858          output_buffer->offset += length;
1859  
1860          current_item = current_item->next;
1861      }
1862  
1863      output_pointer = ensure(output_buffer, output_buffer->format ? (output_buffer->depth + 1) : 2);
1864      if (output_pointer == NULL)
1865      {
1866          return false;
1867      }
1868      if (output_buffer->format)
1869      {
1870          size_t i;
1871          for (i = 0; i < (output_buffer->depth - 1); i++)
1872          {
1873              *output_pointer++ = '\t';
1874          }
1875      }
1876      *output_pointer++ = '}';
1877      *output_pointer = '\0';
1878      output_buffer->depth--;
1879  
1880      return true;
1881  }

