2769  CJSON_PUBLIC(cJSON *) cJSON_Duplicate(const cJSON *item, cJSON_bool recurse)
2770  {
2771      return cJSON_Duplicate_rec(item, 0, recurse );
2772  }

2774  cJSON * cJSON_Duplicate_rec(const cJSON *item, size_t depth, cJSON_bool recurse)
2775  {
2776      cJSON *newitem = NULL;
2777      cJSON *child = NULL;
2778      cJSON *next = NULL;
2779      cJSON *newchild = NULL;
2780  
2781      /* Bail on bad ptr */
2782      if (!item)
2783      {
2784          goto fail;
2785      }
2786      /* Create new item */
2787      newitem = cJSON_New_Item(&global_hooks);
2788      if (!newitem)
2789      {
2790          goto fail;
2791      }
2792      /* Copy over all vars */
2793      newitem->type = item->type & (~cJSON_IsReference);
2794      newitem->valueint = item->valueint;
2795      newitem->valuedouble = item->valuedouble;
2796      if (item->valuestring)
2797      {
2798          newitem->valuestring = (char*)cJSON_strdup((unsigned char*)item->valuestring, &global_hooks);
2799          if (!newitem->valuestring)
2800          {
2801              goto fail;
2802          }
2803      }
2804      if (item->string)
2805      {
2806          newitem->string = (item->type&cJSON_StringIsConst) ? item->string : (char*)cJSON_strdup((unsigned char*)item->string, &global_hooks);
2807          if (!newitem->string)
2808          {
2809              goto fail;
2810          }
2811      }
2812      /* If non-recursive, then we're done! */
2813      if (!recurse)
2814      {
2815          return newitem;
2816      }
2817      /* Walk the ->next chain for the child. */
2818      child = item->child;
2819      while (child != NULL)
2820      {
2821          if(depth >= CJSON_CIRCULAR_LIMIT) {
2822              goto fail;
2823          }
2824          newchild = cJSON_Duplicate_rec(child, depth + 1, true); /* Duplicate (with recurse) each item in the ->next chain */
2825          if (!newchild)
2826          {
2827              goto fail;
2828          }
2829          if (next != NULL)
2830          {
2831              /* If newitem->child already set, then crosswire ->prev and ->next and move on */
2832              next->next = newchild;
2833              newchild->prev = next;
2834              next = newchild;
2835          }
2836          else
2837          {
2838              /* Set newitem->child and move to it */
2839              newitem->child = newchild;
2840              next = newchild;
2841          }
2842          child = child->next;
2843      }
2844      if (newitem && newitem->child)
2845      {
2846          newitem->child->prev = newchild;
2847      }
2848  
2849      return newitem;
2850  
2851  fail:
2852      if (newitem != NULL)
2853      {
2854          cJSON_Delete(newitem);
2855      }
2856  
2857      return NULL;
2858  }

2860  static void skip_oneline_comment(char **input)
2861  {
2862      *input += static_strlen("//");
2863  
2864      for (; (*input)[0] != '\0'; ++(*input))
2865      {
2866          if ((*input)[0] == '\n') {
2867              *input += static_strlen("\n");
2868              return;
2869          }
2870      }
2871  }

2873  static void skip_multiline_comment(char **input)
2874  {
2875      *input += static_strlen("/*");
2876  
2877      for (; (*input)[0] != '\0'; ++(*input))
2878      {
2879          if (((*input)[0] == '*') && ((*input)[1] == '/'))
2880          {
2881              *input += static_strlen("*/");
2882              return;
2883          }
2884      }
2885  }

2887  static void minify_string(char **input, char **output) {
2888      (*output)[0] = (*input)[0];
2889      *input += static_strlen("\"");
2890      *output += static_strlen("\"");
2891  
2892  
2893      for (; (*input)[0] != '\0'; (void)++(*input), ++(*output)) {
2894          (*output)[0] = (*input)[0];
2895  
2896          if ((*input)[0] == '\"') {
2897              (*output)[0] = '\"';
2898              *input += static_strlen("\"");
2899              *output += static_strlen("\"");
2900              return;
2901          } else if (((*input)[0] == '\\') && ((*input)[1] == '\"')) {
2902              (*output)[1] = (*input)[1];
2903              *input += static_strlen("\"");
2904              *output += static_strlen("\"");
2905          }
2906      }
2907  }

2909  CJSON_PUBLIC(void) cJSON_Minify(char *json)
2910  {
2911      char *into = json;
2912  
2913      if (json == NULL)
2914      {
2915          return;
2916      }
2917  
2918      while (json[0] != '\0')
2919      {
2920          switch (json[0])
2921          {
2922              case ' ':
2923              case '\t':
2924              case '\r':
2925              case '\n':
2926                  json++;
2927                  break;
2928  
2929              case '/':
2930                  if (json[1] == '/')
2931                  {
2932                      skip_oneline_comment(&json);
2933                  }
2934                  else if (json[1] == '*')
2935                  {
2936                      skip_multiline_comment(&json);
2937                  } else {
2938                      json++;
2939                  }
2940                  break;
2941  
2942              case '\"':
2943                  minify_string(&json, (char**)&into);
2944                  break;
2945  
2946              default:
2947                  into[0] = json[0];
2948                  json++;
2949                  into++;
2950          }
2951      }
2952  
2953      /* and null-terminate. */
2954      *into = '\0';
2955  }

