3057  CJSON_PUBLIC(cJSON_bool) cJSON_Compare(const cJSON * const a, const cJSON * const b, const cJSON_bool case_sensitive)
3058  {
3059      if ((a == NULL) || (b == NULL) || ((a->type & 0xFF) != (b->type & 0xFF)))
3060      {
3061          return false;
3062      }
3063  
3064      /* check if type is valid */
3065      switch (a->type & 0xFF)
3066      {
3067          case cJSON_False:
3068          case cJSON_True:
3069          case cJSON_NULL:
3070          case cJSON_Number:
3071          case cJSON_String:
3072          case cJSON_Raw:
3073          case cJSON_Array:
3074          case cJSON_Object:
3075              break;
3076  
3077          default:
3078              return false;
3079      }
3080  
3081      /* identical objects are equal */
3082      if (a == b)
3083      {
3084          return true;
3085      }
3086  
3087      switch (a->type & 0xFF)
3088      {
3089          /* in these cases and equal type is enough */
3090          case cJSON_False:
3091          case cJSON_True:
3092          case cJSON_NULL:
3093              return true;
3094  
3095          case cJSON_Number:
3096              if (compare_double(a->valuedouble, b->valuedouble))
3097              {
3098                  return true;
3099              }
3100              return false;
3101  
3102          case cJSON_String:
3103          case cJSON_Raw:
3104              if ((a->valuestring == NULL) || (b->valuestring == NULL))
3105              {
3106                  return false;
3107              }
3108              if (strcmp(a->valuestring, b->valuestring) == 0)
3109              {
3110                  return true;
3111              }
3112  
3113              return false;
3114  
3115          case cJSON_Array:
3116          {
3117              cJSON *a_element = a->child;
3118              cJSON *b_element = b->child;
3119  
3120              for (; (a_element != NULL) && (b_element != NULL);)
3121              {
3122                  if (!cJSON_Compare(a_element, b_element, case_sensitive))
3123                  {
3124                      return false;
3125                  }
3126  
3127                  a_element = a_element->next;
3128                  b_element = b_element->next;
3129              }
3130  
3131              /* one of the arrays is longer than the other */
3132              if (a_element != b_element) {
3133                  return false;
3134              }
3135  
3136              return true;
3137          }
3138  
3139          case cJSON_Object:
3140          {
3141              cJSON *a_element = NULL;
3142              cJSON *b_element = NULL;
3143              cJSON_ArrayForEach(a_element, a)
3144              {
3145                  /* TODO This has O(n^2) runtime, which is horrible! */
3146                  b_element = get_object_item(b, a_element->string, case_sensitive);
3147                  if (b_element == NULL)
3148                  {
3149                      return false;
3150                  }
3151  
3152                  if (!cJSON_Compare(a_element, b_element, case_sensitive))
3153                  {
3154                      return false;
3155                  }
3156              }
3157  
3158              /* doing this twice, once on a and b to prevent true comparison if a subset of b
3159               * TODO: Do this the proper way, this is just a fix for now */
3160              cJSON_ArrayForEach(b_element, b)
3161              {
3162                  a_element = get_object_item(a, b_element->string, case_sensitive);
3163                  if (a_element == NULL)
3164                  {
3165                      return false;
3166                  }
3167  
3168                  if (!cJSON_Compare(b_element, a_element, case_sensitive))
3169                  {
3170                      return false;
3171                  }
3172              }
3173  
3174              return true;
3175          }
3176  
3177          default:
3178              return false;
3179      }
3180  }

