119  int
120  csv_init(struct csv_parser *p, unsigned char options)
121  {
122    /* Initialize a csv_parser object returns 0 on success, -1 on error */
123    if (p == NULL)
124      return -1;
125  
126    p->entry_buf = NULL;
127    p->pstate = ROW_NOT_BEGUN;
128    p->quoted = 0;
129    p->spaces = 0;
130    p->entry_pos = 0;
131    p->entry_size = 0;
132    p->status = 0;
133    p->options = options;
134    p->quote_char = CSV_QUOTE;
135    p->delim_char = CSV_COMMA;
136    p->is_space = NULL;
137    p->is_term = NULL;
138    p->blk_size = MEM_BLK_SIZE;
139    p->malloc_func = NULL;
140    p->realloc_func = realloc;
141    p->free_func = free;
142  
143    return 0;
144  }

146  void
147  csv_free(struct csv_parser *p)
148  {
149    /* Free the entry_buffer of csv_parser object */
150    if (p == NULL)
151      return;
152  
153    if (p->entry_buf && p->free_func)
154      p->free_func(p->entry_buf);
155  
156    p->entry_buf = NULL;
157    p->entry_size = 0;
158  
159    return;
160  }

162  int
163  csv_fini(struct csv_parser *p, void (*cb1)(void *, size_t, void *), void (*cb2)(int c, void *), void *data)
164  {
165    if (p == NULL)
166      return -1;
167  
168    /* Finalize parsing.  Needed, for example, when file does not end in a newline */
169    int quoted = p->quoted;
170    int pstate = p->pstate;
171    size_t spaces = p->spaces;
172    size_t entry_pos = p->entry_pos;
173  
174    if ((pstate == FIELD_BEGUN) && p->quoted && (p->options & CSV_STRICT) && (p->options & CSV_STRICT_FINI)) {
175      /* Current field is quoted, no end-quote was seen, and CSV_STRICT_FINI is set */
176      p->status = CSV_EPARSE;
177      return -1;
178    }
179  
180    switch (pstate) {
181      case FIELD_MIGHT_HAVE_ENDED:
182        p->entry_pos -= p->spaces + 1;  /* get rid of spaces and original quote */
183        entry_pos = p->entry_pos;
184        /*lint -fallthrough */
185      case FIELD_NOT_BEGUN:
186      case FIELD_BEGUN:
187        /* Unnecessary:
188        quoted = p->quoted, pstate = p->pstate;
189        spaces = p->spaces, entry_pos = p->entry_pos;
190        */
191        SUBMIT_FIELD(p);
192        SUBMIT_ROW(p, -1);
193        break;
194      case ROW_NOT_BEGUN: /* Already ended properly */
195        ;
196    }
197  
198    /* Reset parser */
199    p->spaces = p->quoted = p->entry_pos = p->status = 0;
200    p->pstate = ROW_NOT_BEGUN;
201  
202    return 0;
203  }

