281  static int
282  csv_increase_buffer(struct csv_parser *p)
283  {
284    if (p == NULL) return 0;
285    if (p->realloc_func == NULL) return 0;
286    
287    /* Increase the size of the entry buffer.  Attempt to increase size by 
288     * p->blk_size, if this is larger than SIZE_MAX try to increase current
289     * buffer size to SIZE_MAX.  If allocation fails, try to allocate halve 
290     * the size and try again until successful or increment size is zero.
291     */
292  
293    size_t to_add = p->blk_size;
294    void *vp;
295  
296    if ( p->entry_size >= SIZE_MAX - to_add )
297      to_add = SIZE_MAX - p->entry_size;
298  
299    if (!to_add) {
300      p->status = CSV_ETOOBIG;
301      return -1;
302    }
303  
304    while ((vp = p->realloc_func(p->entry_buf, p->entry_size + to_add)) == NULL) {
305      to_add /= 2;
306      if (!to_add) {
307        p->status = CSV_ENOMEM;
308        return -1;
309      }
310    }
311  
312    /* Update entry buffer pointer and entry_size if successful */
313    p->entry_buf = vp;
314    p->entry_size += to_add;
315    return 0;
316  }

318  size_t
319  csv_parse(struct csv_parser *p, const void *s, size_t len, void (*cb1)(void *, size_t, void *), void (*cb2)(int c, void *), void *data)
320  {
321    assert(p && "received null csv_parser");
322  
323    if (s == NULL) return 0;
324    
325    unsigned const char *us = s;  /* Access input data as array of unsigned char */
326    unsigned char c;              /* The character we are currently processing */
327    size_t pos = 0;               /* The number of characters we have processed in this call */
328  
329    /* Store key fields into local variables for performance */
330    unsigned char delim = p->delim_char;
331    unsigned char quote = p->quote_char;
332    int (*is_space)(unsigned char) = p->is_space;
333    int (*is_term)(unsigned char) = p->is_term;
334    int quoted = p->quoted;
335    int pstate = p->pstate;
336    size_t spaces = p->spaces;
337    size_t entry_pos = p->entry_pos;
338  
339  
340    if (!p->entry_buf && pos < len) {
341      /* Buffer hasn't been allocated yet and len > 0 */
342      if (csv_increase_buffer(p) != 0) { 
343        p->quoted = quoted, p->pstate = pstate, p->spaces = spaces, p->entry_pos = entry_pos;
344        return pos;
345      }
346    }
347  
348    while (pos < len) {
349      /* Check memory usage, increase buffer if necessary */
350      if (entry_pos == ((p->options & CSV_APPEND_NULL) ? p->entry_size - 1 : p->entry_size) ) {
351        if (csv_increase_buffer(p) != 0) {
352          p->quoted = quoted, p->pstate = pstate, p->spaces = spaces, p->entry_pos = entry_pos;
353          return pos;
354        }
355      }
356  
357      c = us[pos++];
358  
359      switch (pstate) {
360        case ROW_NOT_BEGUN:
361        case FIELD_NOT_BEGUN:
362          if ((is_space ? is_space(c) : c == CSV_SPACE || c == CSV_TAB) && c!=delim) { /* Space or Tab */
363            continue;
364          } else if (is_term ? is_term(c) : c == CSV_CR || c == CSV_LF) { /* Carriage Return or Line Feed */
365            if (pstate == FIELD_NOT_BEGUN) {
366              SUBMIT_FIELD(p);
367              SUBMIT_ROW(p, c); 
368            } else {  /* ROW_NOT_BEGUN */
369              /* Don't submit empty rows by default */
370              if (p->options & CSV_REPALL_NL) {
371                SUBMIT_ROW(p, c);
372              }
373            }
374            continue;
375          } else if (c == delim) { /* Comma */
376            SUBMIT_FIELD(p);
377            break;
378          } else if (c == quote) { /* Quote */
379            pstate = FIELD_BEGUN;
380            quoted = 1;
381          } else {               /* Anything else */
382            pstate = FIELD_BEGUN;
383            quoted = 0;
384            SUBMIT_CHAR(p, c);
385          }
386          break;
387        case FIELD_BEGUN:
388          if (c == quote) {         /* Quote */
389            if (quoted) {
390              SUBMIT_CHAR(p, c);
391              pstate = FIELD_MIGHT_HAVE_ENDED;
392            } else {
393              /* STRICT ERROR - double quote inside non-quoted field */
394              if (p->options & CSV_STRICT) {
395                p->status = CSV_EPARSE;
396                p->quoted = quoted, p->pstate = pstate, p->spaces = spaces, p->entry_pos = entry_pos;
397                return pos-1;
398              }
399              SUBMIT_CHAR(p, c);
400              spaces = 0;
401            }
402          } else if (c == delim) {  /* Comma */
403            if (quoted) {
404              SUBMIT_CHAR(p, c);
405            } else {
406              SUBMIT_FIELD(p);
407            }
408          } else if (is_term ? is_term(c) : c == CSV_CR || c == CSV_LF) {  /* Carriage Return or Line Feed */
409            if (!quoted) {
410              SUBMIT_FIELD(p);
411              SUBMIT_ROW(p, c);
412            } else {
413              SUBMIT_CHAR(p, c);
414            }
415          } else if (!quoted && (is_space? is_space(c) : c == CSV_SPACE || c == CSV_TAB)) { /* Tab or space for non-quoted field */
416              SUBMIT_CHAR(p, c);
417              spaces++;
418          } else {  /* Anything else */
419            SUBMIT_CHAR(p, c);
420            spaces = 0;
421          }
422          break;
423        case FIELD_MIGHT_HAVE_ENDED:
424          /* This only happens when a quote character is encountered in a quoted field */
425          if (c == delim) {  /* Comma */
426            entry_pos -= spaces + 1;  /* get rid of spaces and original quote */
427            SUBMIT_FIELD(p);
428          } else if (is_term ? is_term(c) : c == CSV_CR || c == CSV_LF) {  /* Carriage Return or Line Feed */
429            entry_pos -= spaces + 1;  /* get rid of spaces and original quote */
430            SUBMIT_FIELD(p);
431            SUBMIT_ROW(p, c);
432          } else if (is_space ? is_space(c) : c == CSV_SPACE || c == CSV_TAB) {  /* Space or Tab */
433            SUBMIT_CHAR(p, c);
434            spaces++;
435          } else if (c == quote) {  /* Quote */
436            if (spaces) {
437              /* STRICT ERROR - unescaped double quote */
438              if (p->options & CSV_STRICT) {
439                p->status = CSV_EPARSE;
440                p->quoted = quoted, p->pstate = pstate, p->spaces = spaces, p->entry_pos = entry_pos;
441                return pos-1;
442              }
443              spaces = 0;
444              SUBMIT_CHAR(p, c);
445            } else {
446              /* Two quotes in a row */
447              pstate = FIELD_BEGUN;
448            }
449          } else {  /* Anything else */
450            /* STRICT ERROR - unescaped double quote */
451            if (p->options & CSV_STRICT) {
452              p->status = CSV_EPARSE;
453              p->quoted = quoted, p->pstate = pstate, p->spaces = spaces, p->entry_pos = entry_pos;
454              return pos-1;
455            }
456            pstate = FIELD_BEGUN;
457            spaces = 0;
458            SUBMIT_CHAR(p, c);
459          }
460          break;
461       default:
462         break;
463      }
464    }
465    p->quoted = quoted, p->pstate = pstate, p->spaces = spaces, p->entry_pos = entry_pos;
466    return pos;
467  }

469  size_t
470  csv_write (void *dest, size_t dest_size, const void *src, size_t src_size)
471  {
472    return csv_write2(dest, dest_size, src, src_size, CSV_QUOTE);
473  }

475  int
476  csv_fwrite (FILE *fp, const void *src, size_t src_size)
477  {
478    return csv_fwrite2(fp, src, src_size, CSV_QUOTE);
479  }

481  size_t
482  csv_write2 (void *dest, size_t dest_size, const void *src, size_t src_size, unsigned char quote)
483  {
484    unsigned char *cdest = dest;
485    const unsigned char *csrc = src;
486    size_t chars = 0;
487  
488    if (src == NULL)
489      return 0;
490  
491    if (dest == NULL)
492      dest_size = 0;
493  
494    if (dest_size > 0)
495      *cdest++ = quote;
496    chars++;
497  
498    while (src_size) {
499      if (*csrc == quote) {
500        if (dest_size > chars)
501          *cdest++ = quote;
502        if (chars < SIZE_MAX) chars++;
503      }
504      if (dest_size > chars)
505        *cdest++ = *csrc;
506      if (chars < SIZE_MAX) chars++;
507      src_size--;
508      csrc++;
509    }
510  
511    if (dest_size > chars)
512      *cdest = quote;
513    if (chars < SIZE_MAX) chars++;
514  
515    return chars;
516  }

518  int
519  csv_fwrite2 (FILE *fp, const void *src, size_t src_size, unsigned char quote)
520  {
521    const unsigned char *csrc = src;
522  
523    if (fp == NULL || src == NULL)
524      return 0;
525  
526    if (fputc(quote, fp) == EOF)
527      return EOF;
528  
529    while (src_size) {
530      if (*csrc == quote) {
531        if (fputc(quote, fp) == EOF)
532          return EOF;
533      }
534      if (fputc(*csrc, fp) == EOF)
535        return EOF;
536      src_size--;
537      csrc++;
538    }
539  
540    if (fputc(quote, fp) == EOF) {
541      return EOF;
542    }
543  
544    return 0;
545  }
